package org.sleepwell.app;

import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.provider.DocumentsContract;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

/** Newly created documents only. A remembered destination is not permission by itself. */
final class CloudBackupProvider implements CloudBackupCopy.Provider {
    private final ContentResolver resolver;private final Uri tree,parent;private final java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean();private final AtomicReference<CancellationSignal> signal=new AtomicReference<>();private final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();
    private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(r,"cloud-backup-cancel"),new ThreadPoolExecutor.DiscardPolicy());
    CloudBackupProvider(Context context,String tree){this.resolver=context.getContentResolver();this.tree=Uri.parse(tree);if(!DocumentsContract.isTreeUri(this.tree)||!"content".equals(this.tree.getScheme()))throw new IllegalArgumentException("Choose an Android document folder.");parent=DocumentsContract.buildDocumentUriUsingTree(this.tree,DocumentsContract.getTreeDocumentId(this.tree));}
    static boolean granted(ContentResolver resolver,Uri tree){for(UriPermission permission:resolver.getPersistedUriPermissions())if(permission.getUri().equals(tree)&&permission.isReadPermission()&&permission.isWritePermission())return true;return false;}
    private void requireGrant()throws IOException{if(!granted(resolver,tree))throw new IOException("Folder access expired. Choose the destination again.");}
    private CancellationSignal fresh(){CancellationSignal owned=new CancellationSignal();signal.set(owned);if(cancelled.get())owned.cancel();return owned;}
    String label()throws IOException{String[] projection={DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_FLAGS};CancellationSignal owned=fresh();try(Cursor c=resolver.query(parent,projection,null,null,null,owned)){if(c==null||!c.moveToFirst()||!DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(1))||(c.getLong(2)&DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE)==0)throw new IOException("Choose a writable document folder.");return c.getString(0);}catch(RuntimeException failure){throw new IOException("Folder is unavailable. Choose it again.");}}
    private Set<String> children()throws IOException{Set<String> ids=new HashSet<>();CancellationSignal owned=fresh();Uri uri=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));try(Cursor c=resolver.query(uri,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null,owned)){if(c==null)throw new IOException("Folder could not be inspected.");while(c.moveToNext()){if(ids.size()>=200)throw new IOException("Choose a dedicated backup folder with fewer than 200 documents.");ids.add(c.getString(0));}}catch(RuntimeException error){throw new IOException("Folder could not be inspected.");}return ids;}
    public CloudBackupCopy.Document create(String name)throws Exception{if(cancelled.get())throw new InterruptedIOException("Cancelled");requireGrant();label();Set<String> before=children();if(before.size()>=200)throw new IOException("Choose a dedicated backup folder with fewer than 200 documents.");Uri created=DocumentsContract.createDocument(resolver,parent,"application/json",name);if(created==null||!Objects.equals(tree.getAuthority(),created.getAuthority())||!DocumentsContract.isTreeUri(created)||!DocumentsContract.getTreeDocumentId(tree).equals(DocumentsContract.getTreeDocumentId(created)))throw new IOException("Provider returned an unexpected document.");String id=DocumentsContract.getDocumentId(created);if(before.contains(id)||!children().contains(id))throw new IOException("Provider did not create a new child document. Nothing was overwritten.");return new CloudBackupCopy.Document(created.toString(),name);}
    private ParcelFileDescriptor open(CloudBackupCopy.Document document,String mode)throws IOException{requireGrant();Uri uri=Uri.parse(document.uri);if(!Objects.equals(uri.getAuthority(),tree.getAuthority())||!DocumentsContract.isTreeUri(uri)||!DocumentsContract.getTreeDocumentId(uri).equals(DocumentsContract.getTreeDocumentId(tree)))throw new IOException("Document is outside the selected folder.");CancellationSignal owned=fresh();ParcelFileDescriptor file=resolver.openFileDescriptor(uri,mode,owned);if(file==null)throw new IOException("Document could not be opened.");descriptor.set(file);return file;}
    public OutputStream output(CloudBackupCopy.Document document)throws IOException{return new ParcelFileDescriptor.AutoCloseOutputStream(open(document,"w"));}
    public InputStream input(CloudBackupCopy.Document document)throws IOException{return new ParcelFileDescriptor.AutoCloseInputStream(open(document,"r"));}
    public void cancel(){cancelled.set(true);CancellationSignal pending=signal.get();ParcelFileDescriptor open=descriptor.get();CANCEL.execute(()->{if(pending!=null)pending.cancel();if(open!=null)try{open.close();}catch(IOException ignored){}});}
    static void choose(Context context,Uri tree,int flags)throws Exception{
        int modes=flags&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(modes!=(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION)||(flags&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)==0)throw new IOException("This provider did not grant remembered read/write folder access.");ContentResolver resolver=context.getContentResolver();int before=0;for(UriPermission permission:resolver.getPersistedUriPermissions())if(permission.getUri().equals(tree)){if(permission.isReadPermission())before|=Intent.FLAG_GRANT_READ_URI_PERMISSION;if(permission.isWritePermission())before|=Intent.FLAG_GRANT_WRITE_URI_PERMISSION;}
        int acquired=modes&~before;boolean remembered=false;try{resolver.takePersistableUriPermission(tree,modes);CloudBackupProvider provider=new CloudBackupProvider(context,tree.toString());String label=provider.label();CloudBackupSettings.Destination old=CloudBackupSettings.destination(CloudBackupSettings.factory.preferences(context));int owned=acquired|(old.tree.equals(tree.toString())?old.owned:0);CloudBackupSettings.remember(CloudBackupSettings.factory.preferences(context),tree.toString(),label,owned);remembered=true;AutoCloudBackups.destinationChanged(context);if(!old.tree.equals(tree.toString()))release(context,old);}finally{if(!remembered&&acquired!=0)try{resolver.releasePersistableUriPermission(tree,acquired);}catch(RuntimeException ignored){}}
    }
    static void disconnect(Context context){CloudBackupSettings.Destination old=CloudBackupSettings.disconnect(CloudBackupSettings.factory.preferences(context));AutoCloudBackups.destinationChanged(context);release(context,old);}
    private static void release(Context context,CloudBackupSettings.Destination destination){if(destination.owned!=0&&!destination.tree.isEmpty())try{context.getContentResolver().releasePersistableUriPermission(Uri.parse(destination.tree),destination.owned);}catch(RuntimeException ignored){}}
}
